('hab_passo_fantasma', 'passo_fantasma', 'Passo Fantasma', 'Some e reaparece atrás do alvo da mira, já golpeando pelas costas.', 'ASSASSINO', 'ALVO', 'SOMBRA', 'minecraft:ender_pearl', 20, 7, 7, 14, 0, 0, 'frx:atras', 0, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_bomba_de_fumaca', 'bomba_de_fumaca', 'Bomba de Fumaça', 'Uma nuvem cega e atrasa quem está perto e faz os monstros esquecerem você. Você some por alguns segundos.', 'ASSASSINO', 'AREA', 'FISICO', 'minecraft:gunpowder', 30, 22, 0, 0, 5, 5, 'frx:fumaca', 0, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_laminas_envenenadas', 'laminas_envenenadas', 'Lâminas Envenenadas', 'Por 12 s, todo golpe seu envenena o alvo. Mortos-vivos definham no lugar do veneno.', 'ASSASSINO', 'BUFF', 'NATUREZA', 'minecraft:spider_eye', 30, 28, 0, 0, 0, 12, 'frx:laminas', 2, 6, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_leque_de_adagas', 'leque_de_adagas', 'Leque de Adagas', 'Arremessa adagas em cone à frente, acertando e empurrando todos.', 'ASSASSINO', 'AREA', 'FISICO', 'minecraft:arrow', 30, 9, 7, 8, 0, 0, 'frx:leque', 0, 7, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_emboscada', 'emboscada', 'Emboscada', 'Fica invisível e veloz por 8 s. O próximo golpe sai 100% mais forte e deixa o alvo paralisado.', 'ASSASSINO', 'BUFF', 'SOMBRA', 'minecraft:phantom_membrane', 35, 26, 0, 0, 0, 8, 'frx:emboscada', 2, 9, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_golpe_de_misericordia', 'golpe_de_misericordia', 'Golpe de Misericórdia', 'Quanto menos vida o alvo tem, mais forte o golpe (até o triplo). Se matar, a recarga zera.', 'ASSASSINO', 'ALVO', 'FISICO', 'minecraft:golden_sword', 35, 16, 8, 5, 0, 0, 'frx:executar', 0, 11, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_adaga_ricochete', 'adaga_ricochete', 'Adaga Ricochete', 'A adaga acerta o alvo e salta por até 4 inimigos próximos, perdendo força a cada salto.', 'ASSASSINO', 'ALVO', 'FISICO', 'minecraft:prismarine_shard', 35, 11, 9, 16, 7, 0, 'frx:ricochete', 4, 13, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_sangria_profunda', 'sangria_profunda', 'Sangria Profunda', 'Um corte fundo: o golpe inicial e depois metade do dano a cada segundo por 8 s.', 'ASSASSINO', 'ALVO', 'FISICO', 'minecraft:nether_wart', 40, 18, 8, 4, 0, 8, 'frx:sangria', 0, 15, false, 'ITEM', CURRENT_TIMESTAMP),
